import React, { useState } from "react";

const Categories = () => {
  const [selected, setSelected] = useState("");

  // Categories
  const categories = [
    { name: "Technology", path: "technology" },
    { name: "Lifestyle", path: "lifestyle" },
    { name: "Travel", path: "travel" },
    { name: "Health", path: "health" },
    { name: "Education", path: "education" },
  ];

  // Blogs with images
  const blogs = {
    technology: [
      {
        title: "Latest Trends in AI",
        desc: "How AI is shaping the future.",
        img: "data:image/jpeg;base64,",
      },
      {
        title: "React vs Angular",
        desc: "A comparison of two giants.",
        img: "data:image/jpeg;base64,",
      },
    ],
    lifestyle: [
      {
        title: "Minimalist Living",
        desc: "Tips for a simpler life.",
        img: "data:image/jpeg;base64,",
      },
      {
        title: "Work-Life Balance",
        desc: "How to balance career & family.",
        img: "data:image/jpeg;base64,",
      },
    ],
    travel: [
      {
        title: "Top 10 Places in Europe",
        desc: "Must-visit destinations.",
        img: "data:image/jpeg;base64,",
      },
      {
        title: "Backpacking Tips",
        desc: "Travel smart on a budget.",
        img: "data:image/jpeg;base64,",
      },
    ],
    health: [
      {
        title: "Healthy Eating",
        desc: "Nutrition tips for a better life.",
        img: "data:image/jpeg;base64,",
      },
      {
        title: "Home Workouts",
        desc: "Stay fit without a gym.",
        img: "data:image/png;base64,",
      },
    ],
    education: [
      {
        title: "Online Learning Platforms",
        desc: "Best websites to learn.",
        img: "data:image/png;base64,",
      },
      {
        title: "Study Hacks",
        desc: "Boost your productivity.",
        img: "data:image/jpeg;base64,",
      },
    ],
  };

  // Dropdown handler
  const handleChange = (e) => {
    setSelected(e.target.value);
  };

  // If no category is selected, show all blogs
  const displayedBlogs = selected
    ? blogs[selected]
    : Object.values(blogs).flat();

  return (
    <div className="w-full flex flex-col items-center py-12 bg-gray-50">
      {/* Heading */}
      <h1 className="text-3xl md:text-4xl font-bold text-center underline !text-black mb-8">
        Categories
      </h1>

      {/* Dropdown */}
      <div className="w-full max-w-md mb-10">
        <label
          htmlFor="categories"
          className="block text-lg font-medium text-gray-700 mb-2 text-center"
        >
          Choose a Category
        </label>
        <select
          id="categories"
          value={selected}
          onChange={handleChange}
          className="w-full px-4 py-3 rounded-lg border border-gray-300 shadow-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-gray-700"
        >
          <option value="">-- Show All Categories --</option>
          {categories.map((cat, index) => (
            <option key={index} value={cat.path}>
              {cat.name}
            </option>
          ))}
        </select>
      </div>

      {/* Blog Grid */}
      <div className="w-full max-w-6xl grid gap-8 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 px-6">
        {displayedBlogs.map((blog, index) => (
          <div
            key={index}
            className="bg-white rounded-lg shadow-md hover:shadow-lg transition overflow-hidden"
          >
            <img
              src={blog.img}
              alt={blog.title}
              className="w-full h-40 object-cover"
            />
            <div className="p-4">
              <h2 className="text-lg font-semibold text-gray-800 mb-2">
                {blog.title}
              </h2>
              <p className="text-gray-600 text-sm">{blog.desc}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Categories;
